#!/usr/bin/env python3
"""Local, data-backed sampling/visibility evidence appendix."""
import html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];out=ROOT/'outputs/quality/SEM-379/r1'
a=json.loads((out/'sampling-audit.json').read_text());d=json.loads((out/'input-diagnostic/result.json').read_text())
panels=''.join(f'<figure><figcaption>{html.escape(x["name"])} · 原生ROI {x["box"]} · {html.escape(x["selection"])}</figcaption><img loading="lazy" src="input-diagnostic/{x["name"]}"></figure>' for x in d['panels'])
samples=''.join(f'<figure><img loading="lazy" src="sampling-panels/{p.name}"></figure>' for p in sorted((out/'sampling-panels').glob('*.png')))
text='''<!doctype html><html lang="zh"><meta charset="utf-8"><title>SEM379 采样与输入证据</title><style>body{margin:32px auto;max-width:1320px;padding:0 20px;font:15px/1.7 system-ui;color:#202830;background:#f7f7f5}figure{margin:24px 0}img{width:100%;height:auto;background:white}figcaption{font-size:12px;color:#56616a}.samples{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.samples img{max-width:440px}h1{font-size:26px}h2{margin-top:36px;font-size:21px}a{color:#246882}</style><h1>SEM379：单变量采样与输入诊断</h1><p>固定RGB140、SEM378控制、seed20260805、原生768裁块、300标签与6000成功更新。此页是训练前诊断；不含候选模型准确率。</p><p><strong>50%保留原裁块，50%按已有GT stay_cable区域定位。</strong>视角和水平翻转序列保持；64px已占据GT网格均匀抽取，再选格内索像素；边界允许时锚点留128px上下文。不按159或模型预测选择训练样本，无放大、融合或后处理。</p><p>6000步实际2948次区域采样、3052次原均匀采样；全300视角覆盖。索曝光+9.03%，未被采到的GT索像素105.9万→23.6万；历史漏检中未见像素30408→10160。背景仍占78.72%。foundation曝光−4.43%，属于待检查代价。240/300视角索曝光增加，60张减少。</p><p>现有GT包含整块索扇区，并非逐根物理索掩码。5×5亮度范围仅为输入细节代理，不能替代索可见性真值：643012个漏检像素中424488在照片/渲染均有局部细节，108659在照片有而渲染弱，106258二者都弱。边界偏移与背景纹理均会影响分类。</p><p>146显示RGB仍有细索而语义断续；241照片斜索清楚，渲染只剩模糊暗带；171的GT整块扇区与垂索间真实水面提示区域语义和物理细索连续性不可混同。所有图均来自同一已有标签/原始预测，未修图。</p><p><a href="sampling-audit.json">完整采样计数</a> · <a href="input-diagnostic/result.json">全300输入诊断</a> · <a href="sampling-plan.jsonl">6000步采样日志</a></p><h2>同位置：照片 / RGB140 / GT / SEM378 / FN与FP</h2><p>固定九视角＋按排序均匀取12视角；各图取最高128px漏检密度的256px ROI。另示全300输入细节损失代理最多的241/171。它们仅用于诊断，不参与定义采样。</p>__PANELS__<h2>首18个不同区域采样视角</h2><p>青框：原随机裁块；紫框：GT区域裁块；红点：GT锚点。相同原生768大小，图仅展示时缩小。</p><div class="samples">__SAMPLES__</div></html>'''
(out/'preflight.html').write_text(text.replace('__PANELS__',panels).replace('__SAMPLES__',samples))
